type Charge = (token: string) => Promise<string>;

export async function chargeWithRetry(
  charge: Charge,
  token: string,
): Promise<string> {
  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      return await charge(token);
    } catch (error) {
      if (attempt === 2) throw error;
    }
  }
  throw new Error("unreachable");
}
